/**
 * Unit tests for org.apache.commons.math.util.MathUtils#factorial
 */
public class MathUtils_factorial_TriageGen1Test {







    @Test
    public void testFactorial_EdgeOfLong() {
        // 20! is the largest factorial that fits in a signed 64-bit long
        // 20! = 2432902008176640000L
        assertEquals(2432902008176640000L, MathUtils.factorial(20));
    }




}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for org.apache.commons.math.util.MathUtils#factorial
 */
public class MathUtils_factorial_TriageGen1Test {









    @Test(expected = ArithmeticException.class)
    public void testFactorial_TooLarge() {
        // 21! exceeds Long.MAX_VALUE
        // Based on the implementation logic, Math.round(factorialDouble(21)) 
        // will result in a value that triggers the ArithmeticException branch
        MathUtils.factorial(21);
    }


}

package org.apache.commons.math.util;

