/**
 * Unit tests for org.apache.commons.math.util.MathUtils#factorial
 */
public class MathUtils_factorial_TriageGen1Test {











    @Test(expected = Exception.class)
    public void testFactorial_Negative() {
        // Factorial of negative numbers is generally not defined for this implementation
        // and would likely cause an ArrayIndexOutOfBoundsException due to factorials[n]
        MathUtils.factorial(-1);
    }
}
